import asyncioimport base64import hashlibimport hmacimport jsonimport loggingimport osimport timefrom datetime import datetime, timezonefrom typing import Optionalimport requestsimport websocketsfrom market_data import (    MarketDataStore,    OrderBookStore,    SymbolRanker,    TradeStore,    OrderFlowAnalyzer,    LiquidityEngine,    SignalGenerator,    SignalConfig,)from event_confirmation import EventConfirmationEngine, EventConfirmationConfigfrom evidence_pipeline import RollingEvidenceAccumulator, RollingEvidenceConfig, PersistenceValidator, evaluate_tickfrom okx_futures_client import OKXFuturesClientfrom execution_engine import DemoFuturesExecutionEngine, ExecutionConfigfrom position_store import PositionHistoryStorefrom signal_store import SignalHistoryStorefrom movement_tracker import MovementTracker, TradeSnapshotStore, MovementTrackerConfiglogging.basicConfig(    level=logging.INFO,    format="%(message)s",    handlers=[logging.FileHandler("okx_futures.log"), logging.StreamHandler()],)log = logging.getLogger()logging.getLogger("httpx").setLevel(logging.WARNING)logging.getLogger("httpcore").setLevel(logging.WARNING)DEMO_TRADING = True# OKX calls this "Demo Trading" (paper trading), not "testnet". Unlike# BitMart, the WS side uses a completely different host (wspap) for demo# trading rather than a URL flag or query param — see test_ws.py.PROD_PUBLIC_WS = "wss://ws.okx.com:8443/ws/v5/public"PROD_PRIVATE_WS = "wss://ws.okx.com:8443/ws/v5/private"DEMO_PUBLIC_WS = "wss://wspap.okx.com:8443/ws/v5/public"DEMO_PRIVATE_WS = "wss://wspap.okx.com:8443/ws/v5/private"PUBLIC_WS_URL = DEMO_PUBLIC_WS if DEMO_TRADING else PROD_PUBLIC_WSPRIVATE_WS_URL = DEMO_PRIVATE_WS if DEMO_TRADING else PROD_PRIVATE_WSPING_INTERVAL_SEC = 15RECONNECT_BASE_DELAY_SEC = 3RECONNECT_MAX_DELAY_SEC = 60HEARTBEAT_INTERVAL_SEC = 30# OKX has no single "all tickers" firehose channel like BitMart's# "futures/ticker" — each instId is subscribed individually. The ticker# channel is subscribed for every live USDT-margined swap up front (needed# to rank symbols); depth/trade channels are only subscribed for the# current watchlist, same as before.TICKER_CHANNEL = "tickers"DEPTH_CHANNEL = "books5"  # top-5 snapshot on every push -- simpler than maintaining an incremental bookDEPTH_LEVELS = 5  # books5 only ever gives 5 levels per sideTRADE_CHANNEL = "trades"# OKX subscribe/unsubscribe messages are capped in practical size, so the# full-universe ticker subscription (and any large watchlist diff) is sent# in batches rather than one giant args array.SUBSCRIBE_BATCH_SIZE = 50WATCHLIST_TOP_N = 15WATCHLIST_WARMUP_SEC = 10WATCHLIST_INTERVAL_SEC = 30SYMBOL_STALE_AFTER_SEC = 30TRADE_WINDOWS_MS = (500, 1000, 2000, 5000)ORDER_FLOW_INTERVAL_SEC = 0.1WHALE_SIZE_MULTIPLIER = 3.0  # a trade at/above this multiple of the window's avg size counts as a whale tradeSIGNAL_INTERVAL_SEC = 1.0# Rolling Evidence Accumulator ticks at this cadence (design target:# 100-200ms) instead of the old once-per-SIGNAL_INTERVAL_SEC instant# decision — this is what lets evidence "accumulate" instead of firing on# a single 1-second read.EVIDENCE_TICK_INTERVAL_SEC = 0.15POSITION_MONITOR_INTERVAL_SEC = 5.0# --- Demo Futures trade settings ---MARGIN_PER_TRADE_USDT = 1.0REQUESTED_LEVERAGE = 100MIN_LEVERAGE_REQUIRED = 50MAX_OPEN_POSITIONS = 5MAX_TOTAL_TRADES = 20TARGET_NET_PROFIT_USDT = 0.07OPEN_TYPE = "isolated"# Only act on higher-conviction signals — we're not in a rush.MIN_SIGNAL_CONFIDENCE = 0.75# --- Rolling Evidence Accumulator / Persistence Validator settings ---ROLLING_WINDOW_SECONDS = 60.0CONFIDENCE_AVERAGE_THRESHOLD = 0.75CONFIDENCE_PEAK_THRESHOLD = 0.75DIRECTION_CONSISTENCY_THRESHOLD = 0.75SIGNAL_PERSISTENCE_SECONDS = 7.0MINIMUM_CONFIRMATION_EVENTS = 2MINIMUM_WHALE_EVENTS = 1MINIMUM_AGGRESSIVE_VOLUME_RATIO = 0.75# Weighted-scoring threshold (out of 100, assuming default weights) — see# evidence_pipeline.py's RollingEvidenceConfig for the per-dimension weights.MIN_EVIDENCE_SCORE = 75.0# Symbols the bot should never subscribe to or trade (OKX instId format).BLACKLISTED_SYMBOLS = {"BTC-USDT-SWAP"}# While scanning is paused (position cap or lifetime trade limit reached),# log a single status line at most this often instead of spamming per tick.STATUS_LOG_INTERVAL_SEC = 30.0# How often to log a per-symbol funnel snapshot (raw signals seen, and the# rolling-evidence stats) — this is the visibility that was missing from# the last 6-hour run: heartbeat/watchlist logs confirmed the bot was# alive and connected, but there was no way to tell whether SignalGenerator# never produced a candidate at all, or candidates were produced but never# cleared the evidence-accumulator bar, or which specific condition (avg# confidence, whale events, etc.) was the blocker.EVIDENCE_LOG_INTERVAL_SEC = 60.0class WatchlistState:    def __init__(self) -> None:        self.symbols = set()        # Set by run_trading_loop once the position cap is hit, so the        # watchlist/order-flow loops stop churning subscriptions and CPU on        # symbol discovery that won't be acted on anyway — only the position        # monitor keeps running and logging.        self.paused = Falsedef _load_db_config() -> dict:    here = os.path.dirname(os.path.abspath(__file__))    candidates = [        os.path.join(here, "db.txt"),        os.path.join(os.path.dirname(here), "db.txt"),    ]    for path in candidates:        if os.path.exists(path):            config = {}            with open(path, "r") as f:                for line in f:                    line = line.strip()                    if not line or line.startswith("#"):                        continue                    if "=" in line:                        k, _, v = line.partition("=")                        config[k.strip()] = v.strip().strip('"')            return config    raise FileNotFoundError(f"db.txt not found in any of: {candidates}")def _clean_secret(value):    if value is None:        return None    if isinstance(value, str):        value = value.strip()        if value.upper() in ("", "NULL"):            return None    return valuedef load_okx_credentials() -> dict:    """Looks for the 'okx' row in the api_keys Supabase table. OKX needs a    passphrase in addition to key/secret (set by you when the key was    created on OKX), so that column has to be populated for this to work.    Mirrors test_ws.py's load_okx_credentials()."""    from supabase import create_client    config = _load_db_config()    sb = create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])    rows = sb.table("api_keys").select("*").execute()    match = next(        (r for r in rows.data or [] if (r.get("exchange_name") or "").strip().lower() == "okx"),        None,    )    if not match:        raise RuntimeError("No 'okx' row found in the api_keys Supabase table")    api_key = _clean_secret(match.get("api_key_demo"))    api_secret = _clean_secret(match.get("api_secret_demo"))    passphrase = _clean_secret(match.get("passphrase"))    missing = [n for n, v in (("api_key", api_key), ("api_secret", api_secret), ("passphrase", passphrase)) if not v]    if missing:        raise RuntimeError(f"OKX credentials incomplete in Supabase — missing: {', '.join(missing)}")    return {"api_key": api_key, "api_secret": api_secret, "passphrase": passphrase}def build_supabase_client():    """Separate client for position_history reads/writes — reuses the same    db.txt config as load_okx_credentials() but keeps that function's    signature (and its callers) unchanged."""    from supabase import create_client    config = _load_db_config()    return create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])def get_outbound_ip():    try:        resp = requests.get("https://api.ipify.org?format=json", timeout=5)        return resp.json().get("ip")    except Exception:        return Nonedef build_login_args(api_key: str, api_secret: str, passphrase: str) -> dict:    timestamp = str(int(time.time()))    message = f"{timestamp}GET/users/self/verify"    sign = base64.b64encode(        hmac.new(api_secret.encode(), message.encode(), hashlib.sha256).digest()    ).decode()    return {"apiKey": api_key, "passphrase": passphrase, "timestamp": timestamp, "sign": sign}async def _keepalive(ws):    # OKX's WS ping/pong is plain text ("ping"/"pong"), not a JSON envelope.    while True:        await asyncio.sleep(PING_INTERVAL_SEC)        try:            await ws.send("ping")        except Exception:            returndef _depth_trade_args(symbols) -> list:    args = []    for s in symbols:        args.append({"channel": DEPTH_CHANNEL, "instId": s})        args.append({"channel": TRADE_CHANNEL, "instId": s})    return argsasync def _send_in_batches(ws, op: str, args: list) -> None:    for i in range(0, len(args), SUBSCRIBE_BATCH_SIZE):        batch = args[i : i + SUBSCRIBE_BATCH_SIZE]        await ws.send(json.dumps({"op": op, "args": batch}))async def _watchlist_loop(ws, ranker: SymbolRanker, order_book: OrderBookStore, trade_store: TradeStore, watchlist_state: WatchlistState):    current = set()    await asyncio.sleep(WATCHLIST_WARMUP_SEC)    while True:        if watchlist_state.paused:            # At the position cap — hold the current subscriptions as-is            # rather than churning them for symbols we won't trade anyway.            await asyncio.sleep(WATCHLIST_INTERVAL_SEC)            continue        top = set(await ranker.top_symbols()) - BLACKLISTED_SYMBOLS        added = top - current        removed = current - top        if removed:            await _send_in_batches(ws, "unsubscribe", _depth_trade_args(removed))            for symbol in removed:                await order_book.remove(symbol)                await trade_store.remove(symbol)        if added:            await _send_in_batches(ws, "subscribe", _depth_trade_args(added))        if added or removed:            current = top            watchlist_state.symbols = set(current)            log.info(f"[watchlist] now tracking {sorted(current)}")        await asyncio.sleep(WATCHLIST_INTERVAL_SEC)def _translate_ticker(row: dict) -> dict:    """OKX 'tickers' channel -> the ticker shape MarketDataStore/SymbolRanker    expect. OKX has no mark-price field on this channel, so mark_price is    approximated with last_price here — fine for signal generation (which    doesn't read mark_price), but monitor_positions() uses the *real*    mark price from get_position() for anything that matters financially."""    pct_change = None    try:        last = float(row.get("last"))        open24h = float(row.get("open24h"))        if open24h:            pct_change = (last - open24h) / open24h    except (TypeError, ValueError):        pass    return {        "symbol": row.get("instId"),        "last_price": row.get("last"),        "mark_price": row.get("last"),        "bid_price": row.get("bidPx"),        "ask_price": row.get("askPx"),        "bid_vol": row.get("bidSz"),        "ask_vol": row.get("askSz"),        "volume_24": row.get("vol24h"),        "range": pct_change if pct_change is not None else 0.0,    }async def _apply_book_snapshot(order_book: OrderBookStore, row: dict) -> None:    """OKX 'books5' pushes a full top-5 snapshot every update (no deltas to    merge), so each side is just replaced wholesale via the existing    apply_depth_update(), same as it already does per-side."""    inst_id = row.get("instId")    if not inst_id:        return    bids = [{"price": lvl[0], "vol": lvl[1]} for lvl in (row.get("bids") or []) if len(lvl) >= 2]    asks = [{"price": lvl[0], "vol": lvl[1]} for lvl in (row.get("asks") or []) if len(lvl) >= 2]    await order_book.apply_depth_update({"symbol": inst_id, "way": 1, "depths": bids})    await order_book.apply_depth_update({"symbol": inst_id, "way": 2, "depths": asks})def _translate_trade(row: dict) -> dict:    return {        "symbol": row.get("instId"),        "price": row.get("px"),        "vol": row.get("sz"),        "side": row.get("side"),  # already "buy"/"sell" -- matches TradeStore's generic side branch        "created_at": row.get("ts"),    }async def run_public(    market_data: MarketDataStore,    order_book: OrderBookStore,    ranker: SymbolRanker,    trade_store: TradeStore,    watchlist_state: WatchlistState,    all_symbols: list,):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[public] connecting to {PUBLIC_WS_URL}")            async with websockets.connect(PUBLIC_WS_URL, ping_interval=None) as ws:                log.info("[public] connected")                delay = RECONNECT_BASE_DELAY_SEC                # No "all tickers" firehose on OKX -- subscribe every live                # USDT swap's ticker individually (batched) so the ranker                # has a full universe to score.                ticker_args = [{"channel": TICKER_CHANNEL, "instId": s} for s in all_symbols]                await _send_in_batches(ws, "subscribe", ticker_args)                keepalive_task = asyncio.create_task(_keepalive(ws))                watchlist_task = asyncio.create_task(_watchlist_loop(ws, ranker, order_book, trade_store, watchlist_state))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[public] non-JSON message: {raw[:200]}")                            continue                        event = msg.get("event")                        arg = msg.get("arg") or {}                        channel = arg.get("channel")                        if event == "subscribe":                            continue  # one ack per instId at startup -- too noisy to log each                        elif event == "unsubscribe":                            continue                        elif event == "error":                            log.error(f"[public] \u274c error: {msg}")                        elif channel == TICKER_CHANNEL:                            for row in msg.get("data") or []:                                ticker = _translate_ticker(row)                                await market_data.update_from_ticker(ticker)                                await ranker.update_from_ticker(ticker)                        elif channel == DEPTH_CHANNEL:                            for row in msg.get("data") or []:                                await _apply_book_snapshot(order_book, row)                        elif channel == TRADE_CHANNEL:                            for row in msg.get("data") or []:                                await trade_store.apply_trade(_translate_trade(row))                finally:                    keepalive_task.cancel()                    watchlist_task.cancel()        except Exception as e:            log.error(f"[public] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def run_heartbeat(market_data: MarketDataStore, order_book: OrderBookStore):    while True:        await asyncio.sleep(HEARTBEAT_INTERVAL_SEC)        symbol_count = await market_data.symbol_count()        book_count = len(await order_book.symbols())        log.info(f"[heartbeat] tracking {symbol_count} tickers, {book_count} order books")async def run_order_flow(order_flow: OrderFlowAnalyzer, watchlist_state: WatchlistState):    while True:        await asyncio.sleep(ORDER_FLOW_INTERVAL_SEC)        if watchlist_state.paused:            continue        symbols = list(watchlist_state.symbols)        if symbols:            await order_flow.recompute(symbols)THIN_SEPARATOR = "-" * 40def _log_signal(signal, confirmation_result=None):    log.info(THIN_SEPARATOR)    log.info(        f"[signal] {signal.direction.upper()} {signal.symbol} "        f"confidence={signal.confidence:.2f} entry={signal.entry_price} "        f"tp={signal.take_profit:.6f} sl={signal.stop_loss:.6f}"    )    log.info(f"[signal] Prerequisites passed: {signal.prerequisites}")    log.info(f"[signal] Reasons: {signal.reasons}")    if confirmation_result is not None:        log.info(f"[signal] Confirmation: {confirmation_result.confirmations}")    log.info(THIN_SEPARATOR)async def run_trading_loop(    market_data: MarketDataStore,    signal_generator: SignalGenerator,    confirmation_engine: EventConfirmationEngine,    execution_engine: DemoFuturesExecutionEngine,    watchlist_state: WatchlistState,    liquidity_engine: Optional[LiquidityEngine] = None,):    """SignalGenerator -> RollingEvidenceAccumulator -> PersistenceValidator ->    EventConfirmationEngine -> ExecutionEngine.    SignalGenerator and EventConfirmationEngine are unchanged and called    exactly as before. What changed: instead of acting the instant a signal    clears confirmation, every tick's (signal, confirmation) pair is folded    into a 60-second rolling window (accumulator), and a trade only fires    once that window's evidence has itself held steady for    SIGNAL_PERSISTENCE_SECONDS (validator). See evidence_pipeline.py.    """    accumulator = RollingEvidenceAccumulator(        RollingEvidenceConfig(            rolling_window_seconds=ROLLING_WINDOW_SECONDS,            confidence_average_threshold=CONFIDENCE_AVERAGE_THRESHOLD,            confidence_peak_threshold=CONFIDENCE_PEAK_THRESHOLD,            direction_consistency_threshold=DIRECTION_CONSISTENCY_THRESHOLD,            signal_persistence_seconds=SIGNAL_PERSISTENCE_SECONDS,            minimum_confirmation_events=MINIMUM_CONFIRMATION_EVENTS,            minimum_whale_events=MINIMUM_WHALE_EVENTS,            minimum_aggressive_volume_ratio=MINIMUM_AGGRESSIVE_VOLUME_RATIO,            min_score_threshold=MIN_EVIDENCE_SCORE,        )    )    validator = PersistenceValidator()    was_blocked = False    last_status_log = 0.0    last_evidence_log = 0.0    raw_signal_counts: dict = {}  # symbol -> count of ticks with a non-None SignalGenerator result since last flush    while True:        await asyncio.sleep(EVIDENCE_TICK_INTERVAL_SEC)        open_count = await execution_engine.open_count()        total_opened = await execution_engine.total_opened()        max_positions = execution_engine.config.max_open_positions        max_total = execution_engine.config.max_total_trades        capacity_block = open_count >= max_positions        total_block = max_total is not None and total_opened >= max_total        blocked = capacity_block or total_block        if blocked and not was_blocked:            reason = (                f"lifetime trade limit reached ({total_opened}/{max_total})"                if total_block                else f"{open_count}/{max_positions} positions open"            )            log.info(                f"[execution] {reason} — pausing signal scans and watchlist subscriptions, "                f"monitoring existing trades only"            )            last_status_log = time.time()        elif was_blocked and not blocked:            log.info(f"[execution] slot freed ({open_count}/{max_positions} open) — resuming signal scans")        was_blocked = blocked        watchlist_state.paused = blocked        if blocked:            # Beyond the one-time transition message above, surface at most            # one status line every STATUS_LOG_INTERVAL_SEC instead of            # re-evaluating (and re-logging) signals we can't act on anyway.            now = time.time()            if now - last_status_log >= STATUS_LOG_INTERVAL_SEC:                log.info(                    f"[status] {open_count}/{max_positions} open positions, "                    f"{total_opened}/{max_total} lifetime trades — monitoring only"                )                last_status_log = now            continue        for symbol in list(watchlist_state.symbols):            if symbol in BLACKLISTED_SYMBOLS:                continue            if await execution_engine.is_blacklisted(symbol):                # Exchange already told us this pair can never be traded                # here (e.g. local compliance restriction) — not a bot                # error, so there's nothing to gain by retrying it.                continue            if await execution_engine.open_count() >= execution_engine.config.max_open_positions:                break            if await execution_engine.has_open_position(symbol):                continue            market = await market_data.get(symbol)            if not market:                continue            # This still calls SignalGenerator exactly as before (cooldown,            # prerequisites, confidence engine, its own short persistence            # check are all untouched). What's new is what happens with the            # result: instead of confirming-and-firing on this one read, it            # gets folded into the rolling window below.            signal = await signal_generator.evaluate(symbol)            if signal is not None:                raw_signal_counts[symbol] = raw_signal_counts.get(symbol, 0) + 1            book_imbalance = None            if liquidity_engine is not None:                liquidity = await liquidity_engine.get(symbol)                if liquidity:                    book_imbalance = liquidity.get("imbalance")            evaluated = await evaluate_tick(                symbol,                signal,                confirmation_engine,                accumulator,                validator,                book_imbalance=book_imbalance,            )            if evaluated is None:                continue            ready_signal, evidence_summary = evaluated            _log_signal(ready_signal)            signal_snapshot = evidence_summary.to_signal_record(                accumulator.config, raw_signal_count=raw_signal_counts.get(symbol, 0)            )            signal_snapshot["price_at_decision"] = ready_signal.entry_price            signal_snapshot["evaluated_at"] = datetime.now(timezone.utc).isoformat()            await execution_engine.try_open_trade(ready_signal, signal_snapshot=signal_snapshot)        now = time.time()        if now - last_evidence_log >= EVIDENCE_LOG_INTERVAL_SEC:            for symbol in sorted(watchlist_state.symbols):                summary = accumulator.summarize(symbol)                raw = raw_signal_counts.get(symbol, 0)                if summary.sample_count == 0 and raw == 0:                    # SignalGenerator never returned anything for this                    # symbol in the whole interval — nothing for the                    # accumulator to have seen either. Worth knowing on                    # its own (it means prerequisites/confidence never                    # cleared even once), so log it plainly rather than                    # skipping silently.                    log.info(f"[evidence] {symbol} no raw signals in the last {EVIDENCE_LOG_INTERVAL_SEC:.0f}s")                    continue                log.info(f"[evidence] {symbol} raw_signals={raw}")                for line in summary.explain(accumulator.config).splitlines():                    log.info(f"[evidence]   {line}")            raw_signal_counts.clear()            last_evidence_log = nowasync def run_position_monitor(execution_engine: DemoFuturesExecutionEngine):    while True:        await asyncio.sleep(POSITION_MONITOR_INTERVAL_SEC)        try:            await execution_engine.monitor_positions()        except Exception:            log.exception("[monitor] error while monitoring open positions")async def run_shutdown_watcher(execution_engine: DemoFuturesExecutionEngine, shutdown_event: asyncio.Event):    """Once the lifetime trade cap has been reached and every trade opened    under it has closed, signal main() to stop the bot so the run can be    reviewed from position_history rather than trading indefinitely."""    while True:        await asyncio.sleep(POSITION_MONITOR_INTERVAL_SEC)        if await execution_engine.trades_exhausted():            total = await execution_engine.total_opened()            log.info(                f"[shutdown] lifetime trade limit reached ({total}/{execution_engine.config.max_total_trades}) "                f"and all positions are closed — stopping the bot for manual review of position_history"            )            shutdown_event.set()            returnasync def run_private(creds: dict):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[private] connecting to {PRIVATE_WS_URL}")            async with websockets.connect(PRIVATE_WS_URL, ping_interval=None) as ws:                log.info("[private] connected \u2014 logging in")                delay = RECONNECT_BASE_DELAY_SEC                login_args = build_login_args(creds["api_key"], creds["api_secret"], creds["passphrase"])                await ws.send(json.dumps({"op": "login", "args": [login_args]}))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[private] non-JSON message: {raw[:200]}")                            continue                        if msg.get("event") == "login":                            if msg.get("code") == "0":                                log.info("[private] \u2705 login successful")                            else:                                log.error(f"[private] \u274c login failed: {msg}")                                log.error("[private] if this key requires IP whitelisting, confirm this machine's outbound IP is whitelisted on OKX")                                await asyncio.sleep(RECONNECT_MAX_DELAY_SEC)                        elif msg.get("event") == "error":                            log.error(f"[private] \u274c error: {msg}")                        else:                            log.info(f"[private] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[private] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def main():    creds = load_okx_credentials()    outbound_ip = get_outbound_ip()    log.info(f"Outbound IP for this machine: {outbound_ip or 'could not determine'}")    log.info(f"Starting OKX Futures bot (demo_trading={DEMO_TRADING})")    okx_client = OKXFuturesClient(        api_key=creds["api_key"],        api_secret=creds["api_secret"],        passphrase=creds["passphrase"],        demo_trading=DEMO_TRADING,    )    instruments = await okx_client.list_swap_instruments()    all_symbols = [i["instId"] for i in instruments if i.get("instId")]    log.info(f"[startup] discovered {len(all_symbols)} live USDT-margined swap instruments")    market_data = MarketDataStore()    order_book = OrderBookStore(depth_levels=DEPTH_LEVELS)    ranker = SymbolRanker(top_n=WATCHLIST_TOP_N, stale_after_sec=SYMBOL_STALE_AFTER_SEC)    trade_store = TradeStore(windows_ms=TRADE_WINDOWS_MS)    trade_store.on_unmapped_way = lambda way, payload: log.warning(f"[trade] unmapped way={way!r} — trade skipped: {payload}")    order_flow = OrderFlowAnalyzer(trade_store, windows_ms=TRADE_WINDOWS_MS, whale_size_multiplier=WHALE_SIZE_MULTIPLIER)    liquidity_engine = LiquidityEngine(order_book)    signal_generator = SignalGenerator(        market_data,        order_flow,        liquidity_engine,        order_book,        SignalConfig(            # New order-flow features — enabled            enable_aggressive_order_detection=True,            enable_whale_detection=True,            enable_trade_intensity=True,            enable_streak_detection=True,            enable_book_imbalance_by_distance=True,        ),    )    confirmation_engine = EventConfirmationEngine(        trade_store,        order_flow,        order_book,        market_data,        liquidity_engine,        EventConfirmationConfig(min_signal_confidence=MIN_SIGNAL_CONFIDENCE),    )    position_store = None    try:        position_store = PositionHistoryStore(build_supabase_client())    except Exception:        log.exception("[position-store] could not initialize — continuing without trade persistence")    signal_store = None    try:        signal_store = SignalHistoryStore(build_supabase_client())    except Exception:        log.exception("[signal-store] could not initialize — continuing without signal-history persistence")    movement_tracker = None    try:        movement_tracker = MovementTracker(market_data, TradeSnapshotStore(build_supabase_client()), MovementTrackerConfig())    except Exception:        log.exception("[movement-tracker] could not initialize — continuing without trade movement tracking")    execution_engine = DemoFuturesExecutionEngine(        okx_client,        ExecutionConfig(            margin_per_trade_usdt=MARGIN_PER_TRADE_USDT,            requested_leverage=REQUESTED_LEVERAGE,            min_leverage_required=MIN_LEVERAGE_REQUIRED,            max_open_positions=MAX_OPEN_POSITIONS,            max_total_trades=MAX_TOTAL_TRADES,            target_net_profit_usdt=TARGET_NET_PROFIT_USDT,            open_type=OPEN_TYPE,        ),        position_store=position_store,        movement_tracker=movement_tracker,        signal_store=signal_store,    )    watchlist_state = WatchlistState()    shutdown_event = asyncio.Event()    tasks = [        asyncio.create_task(run_public(market_data, order_book, ranker, trade_store, watchlist_state, all_symbols)),        asyncio.create_task(run_private(creds)),        asyncio.create_task(run_heartbeat(market_data, order_book)),        asyncio.create_task(run_order_flow(order_flow, watchlist_state)),        asyncio.create_task(run_trading_loop(market_data, signal_generator, confirmation_engine, execution_engine, watchlist_state, liquidity_engine)),        asyncio.create_task(run_position_monitor(execution_engine)),        asyncio.create_task(run_shutdown_watcher(execution_engine, shutdown_event)),    ]    if movement_tracker is not None:        tasks.append(asyncio.create_task(movement_tracker.run_forever()))    await shutdown_event.wait()    for task in tasks:        task.cancel()    await asyncio.gather(*tasks, return_exceptions=True)    log.info("[shutdown] all background tasks stopped — exiting")if __name__ == "__main__":    try:        asyncio.run(main())    except KeyboardInterrupt:        log.info("okx_futures.py stopped.")